#include <string>
#include <algorithm>

int minPurseLength(const std::string& comb1, const std::string& comb2) {
    // Find positions of teeth in comb1 and comb2
    auto pos1 = std::upper_bound(comb1.begin(), comb1.end(), '*');
    auto pos2 = std::upper_bound(comb2.begin(), comb2.end(), '.');
    // Convert positions to indices (0-based)
    int n1 = pos1 - comb1.begin();
    int n2 = pos2 - comb2.begin();

    // Sort both combs
    std::sort(comb1.begin(), comb1.end());
    std::sort(comb2.begin(), comb2.end());

    int sum = 0;
    for (int i = 0; i < n1; ++i) {
        for (int j = 0; j < n2; ++j) {
            if (comb1[i] <= comb2[j]) {
                sum += comb1[i];
            }
        }
    }
    return sum;
}
